const validation  = $('Get Validation').first().json;
const items       = $('Get Items State').all().map(i => i.json);
const guests      = $('Get Guests State').all().map(i => i.json);
const allSels     = $('Get All Selections').all().map(i => i.json);

if (!validation || !validation.party_id) {
  throw new Error('Party not found');
}

// Unclaimed items (remaining_quantity > 0)
const unclaimedItems = items.filter(i => Number(i.remaining_quantity) > 0).map(i => ({
  name:              i.name,
  unit_price_cents:  Number(i.unit_price_cents),
  remaining_quantity: Number(i.remaining_quantity),
  remaining_value_cents: Number(i.remaining_quantity) * Number(i.unit_price_cents)
}));

// Compute guest totals with tip
const partySubtotal = Number(validation.subtotal_required);
const tipPct        = Number(validation.tip_percent);
const partyTipCents = Math.round(partySubtotal * tipPct / 100);

const guestsOut = guests.map(g => {
  const sub = Number(g.subtotal_cents);
  const tip = partySubtotal > 0
    ? Math.round((sub / partySubtotal) * partyTipCents)
    : 0;
  const totalDue = sub + tip;
  return {
    id:              g.id,
    display_name:    g.display_name,
    role:            g.role,
    status:          g.status,
    subtotal_cents:  sub,
    tip_cents:       tip,
    total_due_cents: totalDue,
    amount_paid_cents: Number(g.amount_paid_cents)
  };
});

// Build my_selections map for the requesting guest (if join_token provided)
const mySelectionsMap = {};
allSels.forEach(s => {
  if (!mySelectionsMap[s.guest_id]) mySelectionsMap[s.guest_id] = [];
  mySelectionsMap[s.guest_id].push({ item_id: s.item_id, quantity: Number(s.quantity) });
});

return [{
  json: {
    party: {
      id:              validation.party_id,
      party_code:      validation.party_code,
      status:          validation.status,
      restaurant_name: validation.restaurant_name,
      tip_percent:     Number(validation.tip_percent)
    },
    validation: {
      subtotal_required:    Number(validation.subtotal_required),
      subtotal_claimed:     Number(validation.subtotal_claimed),
      bucket_empty:         validation.bucket_empty,
      subtotal_match:       validation.subtotal_match,
      party_can_pay:        validation.party_can_pay,
      remaining_value_cents: Number(validation.remaining_value_cents),
      party_tip_cents:      partyTipCents,
      party_total_cents:    Number(validation.subtotal_required) + partyTipCents
    },
    items,
    guests:           guestsOut,
    unclaimed_items:  unclaimedItems,
    all_selections:   mySelectionsMap
  }
}];
